use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input_str = input.as_str().unwrap();
    let mut result = String::new();
    for c in input_str.chars() {
        if c.is_alphabetic() {
            let is_uppercase = c.is_uppercase();
            let new_char = match c {
                c if c.is_lowercase() => c.to_uppercase(),
                c if c.is_uppercase() => c.to_lowercase(),
                c if c.is_lowercase() => c.to_uppercase(),
                c if c.is_uppercase() => c.to_lowercase(),
                c if c.is_uppercase() => c.to_uppercase(),
                c if c.is_lowercase() => c.to_uppercase(),
                c if c.is_lowercase() => c.to_lowercase(),
                _ => c,
            };
            result.push(new_char);
        } else {
            result.push(c);
        }
    }
    Value::String(result)
